-- DUM SULTANATE schema (MySQL 8 / phpMyAdmin). Generated by build_sql.js
CREATE DATABASE IF NOT EXISTS dum_sultanate CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dum_sultanate;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS reviews, favorites, otp_codes, biryanis, users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id VARCHAR(20) NOT NULL UNIQUE,
 name VARCHAR(120) NOT NULL,
 email VARCHAR(190) NOT NULL UNIQUE,
 avatar_url VARCHAR(500) NULL,
 auth_provider ENUM('google','email') NOT NULL DEFAULT 'email',
 is_verified TINYINT(1) NOT NULL DEFAULT 0,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX idx_users_provider(auth_provider)
) ENGINE=InnoDB;
CREATE TABLE biryanis(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 slug VARCHAR(120) NOT NULL UNIQUE,
 name VARCHAR(160) NOT NULL,
 region VARCHAR(120) NOT NULL,
 description TEXT NOT NULL,
 prep_time SMALLINT UNSIGNED NOT NULL,
 cook_time SMALLINT UNSIGNED NOT NULL,
 ingredients_json JSON NOT NULL,
 steps_json JSON NOT NULL,
 INDEX idx_biryanis_region(region)
) ENGINE=InnoDB;
CREATE TABLE favorites(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 biryani_id INT UNSIGNED NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_fav(user_id,biryani_id),
 CONSTRAINT fk_fav_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 CONSTRAINT fk_fav_biryani FOREIGN KEY(biryani_id) REFERENCES biryanis(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE reviews(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 biryani_name VARCHAR(160) NOT NULL,
 rating TINYINT UNSIGNED NOT NULL,
 highlights VARCHAR(255) NULL,
 complaints_improvements TEXT NULL,
 comments TEXT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX idx_reviews_biryani(biryani_name),
 INDEX idx_reviews_user(user_id),
 CONSTRAINT fk_rev_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 CONSTRAINT chk_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB;
CREATE TABLE otp_codes(
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 email VARCHAR(190) NOT NULL,
 code_hash VARCHAR(255) NOT NULL,
 name VARCHAR(120) NOT NULL,
 attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,
 expires_at DATETIME NOT NULL,
 INDEX idx_otp_email(email)
) ENGINE=InnoDB;
INSERT INTO biryanis(slug,name,region,description,prep_time,cook_time,ingredients_json,steps_json) VALUES
('dindigul-thalappakatti-style','Dindigul Thalappakatti Style','Dindigul, Tamil Nadu','Seeraga samba rice and a ghee punch, built on a peppery shallot masala.',30,50,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Thalappakatti special ground masala 2 tbsp","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Fry 10 shallots with the special masala in ghee until the oil floats, then fold in the chicken. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('ambur-nawab-dum-biryani','Ambur Nawab Dum Biryani','Ambur, Tamil Nadu','Red chilli paste biryani on short-grain rice, served with a tangy brinjal dalcha.',35,50,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Red chilli paste 2 tbsp (8 dried Kashmiri chillies, ground)","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Stir the red chilli paste into the masala and cook until it darkens. Serve with dalcha. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('chennai-bhai-veetu-kalyana-biryani','Chennai Bhai Veetu Kalyana Biryani','Chennai, Tamil Nadu','Wedding-style biryani with fragrant basmati and a heap of crisp birista.',30,45,'["Chicken 500 g, bone-in","Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Fried onions (birista) 1 cup","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Layer half the birista between rice and chicken, keeping the rest for the top. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('vaniyambadi-royal-dum','Vaniyambadi Royal Dum','Vaniyambadi, Tamil Nadu','Pakka dum: raw marinated chicken and rice layered and sealed to cook in its own steam.',40,55,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Wheat dough 1 cup for sealing","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Layer the marinated chicken, then parboiled rice, and seal the pot rim with dough. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('kongunadu-country-chicken-biryani','Kongunadu Country Chicken Biryani','Coimbatore, Tamil Nadu','Country chicken with a shallot and fresh coriander paste for an earthy green heat.',30,70,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Shallot-coriander paste 1/2 cup","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Cook the paste with country chicken until tender before adding rice; it needs extra time. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('chettinad-pepper-kalpasi-biryani','Chettinad Pepper & Kalpasi Biryani','Karaikudi, Tamil Nadu','Black stone flower and freshly ground pepper-heavy spices.',30,50,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Kalpasi (black stone flower) 2 g with freshly ground pepper 1 tsp","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Dry-roast kalpasi, pepper, fennel and star anise, then grind and add to the masala. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('madurai-military-style-chicken-biryani','Madurai Military Style Chicken Biryani','Madurai, Tamil Nadu','Dark, rustic, no-nonsense biryani with a pronounced pepper and chilli kick.',25,45,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Military hotel masala 2 tbsp","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Brown the masala hard in oil, then cook chicken in it until almost dry. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('thoothukudi-tirunelveli-coconut-milk-biryani','Thoothukudi / Tirunelveli Coconut Milk Biryani','Thoothukudi, Tamil Nadu','Rice cooked in thick coconut milk for a rounded, gently sweet finish.',30,50,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Thick coconut milk 250 ml","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Replace 250 ml of the water with thick coconut milk and add it after the first boil. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('sivakasi-dum-biryani','Sivakasi Dum Biryani','Sivakasi, Tamil Nadu','Tomato-forward and spicy, with a roasted podi masala base.',30,45,'["Chicken 500 g, bone-in","Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Podi masala 2 tbsp and 3 extra tomatoes","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Cook the extra tomatoes down with the podi masala into a thick, jammy base. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('salem-rr-style-biryani','Salem RR Style Biryani','Salem, Tamil Nadu','Short-grain biryani with a mild, balanced masala that lets the meat lead.',30,45,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","RR-style biryani masala 2 tbsp","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Keep the heat moderate and add the masala late to keep the finish light. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('hyderabadi-kacchi-dum-biryani','Hyderabadi Kacchi Dum Biryani','Hyderabad, Telangana','Raw marinated chicken layered with 70% cooked basmati and sealed.',45,60,'["Chicken 500 g, bone-in","Aged Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Saffron 1 pinch in 3 tbsp warm milk","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Layer raw marinated chicken, then rice, then saffron milk, and seal for dum. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('malabar-thalassery-biryani','Malabar / Thalassery Biryani','Thalassery, Kerala','Short-grain khyma rice finished with fried raisins and cashews.',30,50,'["Chicken 500 g, bone-in","Khyma Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Cashews 2 tbsp and raisins 2 tbsp, fried in ghee","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Fry cashews and raisins in ghee and scatter them between the layers. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('bangalore-donne-biryani','Bangalore Donne Biryani','Bangalore, Karnataka','Green mint and coriander masala, traditionally served in eco-friendly leaf cups.',30,45,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Mint-coriander paste 1 cup","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Fry the green paste until the raw smell goes and the colour deepens. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('andhra-guntur-chilli-fiery-biryani','Andhra Guntur Chilli Fiery Biryani','Guntur, Andhra Pradesh','Fiery, with Guntur chillies and a sharp tang.',25,45,'["Chicken 500 g, bone-in","Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Guntur chilli powder 2 tbsp","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Add Guntur chilli powder with the tomatoes, and keep a cooling raita ready. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('kozhikode-mild-dum-biryani','Kozhikode Mild Dum Biryani','Kozhikode, Kerala','A gentle, aromatic dum with a ghee-rich rice and no heavy chilli.',30,50,'["Chicken 500 g, bone-in","Kaima (Jeerakasala) Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Whole spices (cardamom, cloves, cinnamon) 1 tbsp","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Keep chilli light and let the whole spices perfume the ghee. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('bezawada-crispy-boneless-chicken-biryani','Bezawada Crispy Boneless Chicken Biryani','Vijayawada, Andhra Pradesh','Crispy fried boneless chicken pieces folded through spicy rice.',30,40,'["Chicken 500 g, bone-in","Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Corn flour 3 tbsp for the crisp coating","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Coat boneless chicken in corn flour, shallow-fry until crisp, then fold in at the end. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('claypot-matka-dum-chicken-biryani','Claypot / Matka Dum Chicken Biryani','Tamil Nadu','Cooked and served in clay, which holds steam and adds an earthy aroma.',30,60,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","One clay pot (matka) and dough 1 cup","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Cook and seal inside a pre-soaked clay pot over very low heat. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('bamboo-smoked-chicken-biryani','Bamboo Smoked Chicken Biryani','Nilgiris style','Biryani cooked in bamboo, with smoke from burning coals.',40,60,'["Chicken 500 g, bone-in","Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Hot charcoal piece 1 and ghee 1 tsp for smoking","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Place a hot charcoal in a steel cup, pour ghee over it, cover and smoke for 5 minutes. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('lucknowi-awadhi-royal-saffron-biryani','Lucknowi / Awadhi Royal Saffron Biryani','Lucknow, Uttar Pradesh','Subtle, perfumed and saffron-gold; mild spice with rose and kewra.',40,60,'["Chicken 500 g, bone-in","Aged Basmati Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Saffron 1 pinch and kewra water 1 tsp","Water 750 ml (rice to water 1:1.5)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Sprinkle saffron milk and kewra water over the top layer before sealing. Cook the chicken until 80% done.","Add 750 ml water (1:1.5) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]'),
('south-tamil-street-style-chicken-biryani-with-egg-bonda','South Tamil Street-Style Chicken Biryani with Egg Bonda','Tamil Nadu','Spicy street-stall biryani served alongside fried egg bondas.',35,50,'["Chicken 500 g, bone-in","Seeraga Samba Rice 500 g, washed and soaked 30 min","Curd 100 ml","Ghee 4 tbsp","Oil 3 tbsp","Onions 3 large, sliced","Tomatoes 2 medium","Ginger-garlic paste 2 tbsp","Green chillies 4","Mint and coriander leaves 1/2 cup","Whole spices 1 tbsp","Salt 2 tsp","Besan 1 cup and 4 boiled eggs for bonda","Water 875 ml (rice to water 1:1.75)"]','["Wash the rice and soak it for 30 minutes, then drain.","Marinate the chicken with curd, ginger-garlic paste, salt and chilli powder for 30 minutes.","Heat ghee and oil, add whole spices, then fry the onions until golden. Set aside a handful as birista.","Add tomatoes, green chillies, mint and coriander. Cook until the oil separates.","Coat boiled eggs in spiced besan batter, deep-fry and serve with the biryani. Cook the chicken until 80% done.","Add 875 ml water (1:1.75) and salt. Bring to a rolling boil, add the rice, and cook until 70% done.","Cover with a tight lid or seal with dough. Put it on dum over the lowest heat for 20 minutes.","Rest 10 minutes, fluff gently, and garnish with birista and coriander."]');
